/**
 * Hook: useAIStudioTurnNodes
 *
 * Feeds the SmartScrollbar on AI Studio straight from the page DOM.
 *
 * Why not the conversation messages store, like Gemini: AI Studio's API carries no
 * message ids at all, and the `turn-<UUID>` ids on `ms-chat-turn` are generated by
 * the client on every render. Nothing stored can be matched to an element, so the
 * DOM is the only reliable source for *which* turns exist and *where* they are.
 *
 * DOM facts this relies on (checked against the live page):
 * - Every turn of the prompt is an `ms-chat-turn#turn-<UUID>`, all present at
 *   once (no history paging). The role sits on an inner `[data-turn-role]`.
 * - Turn bodies are virtualised: off-screen turns keep their outer box but their
 *   text is replaced by a height placeholder, so text cannot be read from them.
 * - AI Studio's own scrollbar (`ms-items-scrollbar`) has one button per user turn,
 *   `#scrollbar-item-<UUID>`, whose `aria-label` is the question cut to ~40 chars.
 *
 * Text comes in two tiers: the native button's label is always there; the full
 * question is taken from the store by position among user messages, but only when
 * its start agrees with that label. A mismatch (e.g. an image-only turn that the
 * parser skipped) just means a shorter tooltip — never a jump to the wrong turn.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import throttle from 'lodash/throttle';
import { useUrl } from '@/shared/hooks/useUrl';
import { useConversationMessagesStore } from '@/shared/lib/conversation-messages-store';
import type { SmartScrollbarItem } from '@/entrypoints/overlay.content/shared/components/smart-scrollbar/SmartScrollbarView';

export const AISTUDIO_SCROLLER_SELECTOR = 'ms-autoscroll-container';
/** The chat column; the bar is pinned to its right edge, clear of the run settings panel */
export const AISTUDIO_CHAT_COLUMN_SELECTOR = '.chat-container';

const TURN_SELECTOR = 'ms-chat-turn';
const USER_ROLE_SELECTOR = '[data-turn-role="User"]';

const SCROLL_DEBOUNCE_MS = 80;
const REFRESH_THROTTLE_MS = 250;
/** Keep auto-detection from overriding a click while the smooth scroll runs */
const CLICK_LOCK_MS = 1500;
/** Time for the smooth scroll to land before checking whether layout moved it */
const SETTLE_DELAY_MS = 450;
/** Retry interval while the chat view has not been rendered yet */
const RESOLVE_RETRY_MS = 500;

interface DomTurn {
  id: string;
  label: string;
  renderedText: string;
}

const normalize = (s: string) => s.replace(/\s+/g, ' ').trim();

function readUserTurns(): HTMLElement[] {
  return Array.from(document.querySelectorAll<HTMLElement>(TURN_SELECTOR)).filter(
    (turn) => !!turn.id && !!turn.querySelector(USER_ROLE_SELECTOR),
  );
}

function readDomTurns(): DomTurn[] {
  return readUserTurns().map((turn) => {
    const uuid = turn.id.replace(/^turn-/, '');
    const label =
      document.getElementById(`scrollbar-item-${uuid}`)?.getAttribute('aria-label') ?? '';
    // Only present while the turn is rendered; the leading role caption is dropped
    const renderedText = normalize(
      (turn.querySelector('.turn-content') as HTMLElement | null)?.innerText ?? '',
    ).replace(/^User\s*/, '');
    return { id: turn.id, label, renderedText };
  });
}

/** The label is the question cut short with a trailing ellipsis. */
function labelPrefix(label: string): string {
  return normalize(label).replace(/(\.{3}|…)$/, '').trim();
}

function textsAgree(full: string, prefix: string): boolean {
  if (!prefix) return false;
  const a = normalize(full);
  return a.startsWith(prefix) || prefix.startsWith(a);
}

const sameTurns = (a: DomTurn[], b: DomTurn[]) =>
  a.length === b.length &&
  a.every(
    (t, i) => t.id === b[i].id && t.label === b[i].label && t.renderedText === b[i].renderedText,
  );

export function useAIStudioTurnNodes() {
  const { path } = useUrl();
  const messages = useConversationMessagesStore((s) => s.messages);

  const [scroller, setScroller] = useState<HTMLElement | null>(null);
  const [turns, setTurns] = useState<DomTurn[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const lockUntilRef = useRef(0);
  const activeRef = useRef<string | null>(null);
  useEffect(() => {
    activeRef.current = activeId;
  }, [activeId]);

  // ── Resolve the scroll container (recreated on SPA navigation) ──────
  useEffect(() => {
    setTurns([]);
    setActiveId(null);

    let timer: ReturnType<typeof setTimeout> | null = null;
    const resolve = () => {
      const el = document.querySelector<HTMLElement>(AISTUDIO_SCROLLER_SELECTOR);
      if (el) {
        setScroller(el);
        return;
      }
      setScroller(null);
      timer = setTimeout(resolve, RESOLVE_RETRY_MS);
    };
    resolve();
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [path]);

  // ── Active-turn detection ────────────────────────────────────────────
  const detectActive = useCallback(() => {
    if (Date.now() < lockUntilRef.current || !scroller?.isConnected) return;

    const userTurns = readUserTurns();
    if (!userTurns.length) return;

    // Last user turn whose top has passed the middle of the chat viewport
    const rect = scroller.getBoundingClientRect();
    const line = rect.top + rect.height / 2;
    let best: HTMLElement = userTurns[0];
    for (const turn of userTurns) {
      if (turn.getBoundingClientRect().top <= line) best = turn;
      else break;
    }
    if (best.id !== activeRef.current) setActiveId(best.id);
  }, [scroller]);

  // ── Turn list: initial read + MutationObserver ───────────────────────
  useEffect(() => {
    if (!scroller) return;

    const refresh = throttle(
      () => {
        // The container was swapped out (navigation inside the same path)
        if (!scroller.isConnected) {
          setScroller(document.querySelector<HTMLElement>(AISTUDIO_SCROLLER_SELECTOR));
          return;
        }
        const next = readDomTurns();
        setTurns((prev) => (sameTurns(prev, next) ? prev : next));
        detectActive();
      },
      REFRESH_THROTTLE_MS,
      { leading: true, trailing: true },
    );

    // Native scrollbar labels live outside the scroll container
    const observeRoot = scroller.closest('ms-chat-session') ?? scroller;
    const observer = new MutationObserver(refresh);
    observer.observe(observeRoot, { childList: true, subtree: true });
    refresh();

    return () => {
      observer.disconnect();
      refresh.cancel();
    };
  }, [scroller, detectActive]);

  // ── Scroll listener ──────────────────────────────────────────────────
  useEffect(() => {
    if (!scroller) return;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const onScroll = () => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(detectActive, SCROLL_DEBOUNCE_MS);
    };
    scroller.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      scroller.removeEventListener('scroll', onScroll);
      if (timer) clearTimeout(timer);
    };
  }, [scroller, detectActive]);

  // ── Jump ─────────────────────────────────────────────────────────────
  const scrollToNode = useCallback(
    (id: string) => {
      const turn = document.getElementById(id);
      if (!turn || !scroller) return;

      setActiveId(id);
      lockUntilRef.current = Date.now() + CLICK_LOCK_MS;
      turn.scrollIntoView({ block: 'start', behavior: 'smooth' });

      // Turns above the target swap placeholders for real content as they come
      // into view, which shifts the landing spot. Correct once it has settled.
      setTimeout(() => {
        if (!turn.isConnected) return;
        const offset = turn.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
        if (Math.abs(offset) > 8) turn.scrollIntoView({ block: 'start', behavior: 'auto' });
      }, SETTLE_DELAY_MS);
    },
    [scroller],
  );

  // ── Items ────────────────────────────────────────────────────────────
  const items: SmartScrollbarItem[] = useMemo(() => {
    const storeUsers = messages.filter((m) => m.role === 'user');
    return turns.map((turn, index) => {
      const prefix = labelPrefix(turn.label);
      const candidate = storeUsers[index]?.content ?? '';
      const fromStore =
        candidate &&
        (textsAgree(candidate, prefix) ||
          // No label to check against: accept by position only when counts line up
          (!prefix && storeUsers.length === turns.length && textsAgree(candidate, turn.renderedText)))
          ? candidate
          : '';
      return {
        id: turn.id,
        content: fromStore || turn.renderedText || prefix || `#${index + 1}`,
        available: true,
      };
    });
  }, [turns, messages]);

  return { items, activeId, scrollToNode, scroller };
}
